/*
 * 0_cell_detection_panc_v3.groovy   (v3 copy of scripts/0_cell_detection_panc.groovy; the original is unchanged)
 *
 * Workflow step 1: InstanSeg cell detection over every REGION annotation -- Tissue AND pLN -- ONLY.
 *
 * v3 changes (every other rule of the original is kept, see below):
 *   - REGION_CLASSES = Tissue, pLN. A pancreatic lymph node drawn as its own annotation, disjoint from
 *     the Tissue polygon (6533 6.5 mm away, HDL112 127 um, HDL115 58 um, 6551 touching along ~42 um with
 *     zero shared area), used to need a second run with the region class edited by hand. Each pLN is now:
 *       disjoint  (shares <= MAX_REGION_OVERLAP_UM2 with Tissue)  -> segmented as a region of its own;
 *       contained (>= CONTAINED_MIN_FRACTION of its area inside Tissue) -> NOT selected: the Tissue pass
 *                  already segments it (selecting it too would segment its cells twice); step 8 parents
 *                  those cells to the pLN;
 *       partial   (anything in between) -> refused: selecting it double-segments the overlap, skipping it
 *                  leaves the part outside Tissue without cells. Fix the annotation.
 *     Any two SELECTED regions sharing more than MAX_REGION_OVERLAP_UM2 are refused the same way, and the
 *     overlaps are reported.
 *   - children of EVERY selected region are parked at the root during detection and restored afterwards.
 *   - every selected region must receive detections, or nothing is saved.
 *   - before saving, data.qpdata is re-stat'ed: if it changed since the step began (the run_v3 driver's
 *     record, passed as args[0] = its step_config.json; otherwise the state when this script started),
 *     the script refuses to save over it. It also refuses to START a save within the driver's save margin
 *     of the step's deadline (a save cut short leaves data.qpdata half-written and data.qpdata.bkp behind).
 *   - failures throw (with the reason) instead of `return`: under run_v3 a top-level return would end the
 *     run silently, without the footer.
 *   - the outcome (regions, per-region detections, overlaps, InstanSeg result, duplicate check, save) is
 *     reported in V3_RESULT for the run_v3 provenance record.
 *
 * WHY THIS SCRIPT EXISTS
 * ----------------------
 * Detection used to be a manual GUI step — the only unscripted stage in the pipeline — and it
 * silently corrupted 8 of 20 donors. The QuPath workflow history shows the affected runs used:
 *
 *     selectAnnotations()            <-- selects Tissue AND every nested Islet_N child
 *     InstanSeg...detectObjects()
 *
 * InstanSeg's detectObjects() runs inference once per SELECTED parent object and does not
 * deduplicate across parents (PruneObjectOutputHandler dedupes only across tiles WITHIN one
 * parent). So every nucleus inside an islet was segmented twice — once under Tissue, once under
 * its islet. The two passes tile from different ROI origins, so the copies are near-identical but
 * not equal: centroids ~1 px apart, areas within a fraction of a percent, different vertex counts,
 * two distinct UUIDs. 8_hierarchy_parenting.groovy then re-parents both to the islet, which is why
 * 100% of the duplicates landed in islet cores.
 *
 * Measured damage: 155,669 duplicate pairs across donors 6450, 6505, 6523, 6534, 6566, 6591, 6623.
 * Roughly half to two-thirds of every islet cell in those donors was a duplicate. Nothing
 * downstream detected it — the UUIDs are distinct, so every uniqueness check passed.
 *
 * THE RULES THIS SCRIPT ENFORCES
 * ------------------------------
 *   1. NEVER selectAnnotations(). Select the region annotations explicitly, by classification, and hand
 *      exactly that list to InstanSeg.
 *   2. Protect annotations below each region. QuPath 0.7.0's PixelProcessor (used by InstanSeg) calls
 *      clearChildObjects() on every parent it processes, which would detach Islet / IsletExpanded /
 *      vessel annotations. They are parked at the root during detection and restored afterwards
 *      (names and "Islet: UID" untouched). A region nested inside another selected region, or two
 *      selected regions that overlap, are refused.
 *   3. removeDetections() first, so a re-run replaces rather than accumulates.
 *   4. Verify the InstanSeg result and that no two detections share a centroid; throw (and do not
 *      save) if either check fails. Since 2026-09-28: outlines < DEBRIS_MAX_UM2 are not checked, and up
 *      to DUP_RESOLVE_MAX_FRACTION of the detections (at least 10 pairs) in duplicate pairs are resolved
 *      by dropping the second copy (logged with positions); more still fails. 0 = the strict rule.
 *
 * Normally run BEFORE 1_panc_objects.groovy. Re-detecting an image that already has islets is
 * supported (rule 2); afterwards re-run 2 -> 3 -> 8 (4 is independent of detections).
 *
 * Headless (run_v3.sh passes its step_config.json as the only argument):
 *   /home/smith6jt/QuPath/bin/QuPath script \
 *       --project /home/smith6jt/IO60panc2nd/project.qpproj \
 *       --image "6539_Scan1.er.qptiff - resolution #1" \
 *       /home/smith6jt/IO60panc2nd/scripts/v3/qupath/0_cell_detection_panc_v3.groovy
 */

import qupath.lib.images.servers.ColorTransforms
import com.google.gson.JsonParser
import org.locationtech.jts.operation.union.UnaryUnionOp
import java.nio.file.Files
import java.util.concurrent.TimeUnit

// ==================== PARAMETERS ====================
// Matches every run recorded in the project workflow history (QuPath 0.7.0).
String MODEL_PATH   = "/home/smith6jt/QuPath/v0.7/instanseg/downloaded/fluorescence_nuclei_and_cells-0.1.1"
String DEVICE       = "gpu0"      // "cpu" if no CUDA device
int    TILE_DIMS    = 512
int    PAD          = 32
int    N_THREADS    = 12
boolean MAKE_MEASUREMENTS = false // measurements come from 2_fast_cell_measurements.groovy
List<String> REGION_CLASSES = ["Tissue", "pLN"]   // every annotation of these classes is segmented
String TISSUE_CLASS = "Tissue"    // the containing region: a pLN inside it is segmented with it
double CONTAINED_MIN_FRACTION = 0.99   // a pLN with >= 99% of its area inside Tissue counts as contained
double MAX_REGION_OVERLAP_UM2 = 10.0   // "disjoint": two segmented regions share at most this area
                                       // (~1/5 of a cell; 6551's pLN touches Tissue with 0.0 shared area)
double PIXEL_SIZE_UM = 0.5078     // same value 1_panc_objects.groovy sets; InstanSeg derives its downsample from it
// IO60pLN: the pancreas script's 13 inputs minus CD99, which the 56-channel pLN panel does not carry
List<String> INPUT_CHANNELS = ["DAPI", "CD68", "CD44", "Vimentin", "E-cadherin", "M2Gal3", "HLA-A",
                               "Pan-Cytokeratin", "CD79a", "CD3e", "Beta-actin", "Iba1"]
double DUP_RADIUS_UM = 1.0        // post-run duplicate check; matches phenocycler.cell_qc
double DUP_AREA_TOL  = 0.15
// Outlines smaller than this are debris, not cells (they cover ~no pixel; see the footer's cells_measured): they are
// left out of the duplicate check. The downstream geometry QC drops < 20 um^2 anyway.
double DEBRIS_MAX_UM2 = 5.0
// Duplicate pairs of real cells up to this fraction of all detections (at least 10) are resolved by dropping the second
// copy, each logged with its position; more than that fails as before (the v2 double segmentation had ~22,000 pairs per
// donor). 0 restores the strict rule (any pair fails). 6539 (503,235 cells) had exactly one pair.
double DUP_RESOLVE_MAX_FRACTION = 1e-4
double SAVE_MARGIN_MIN_DEFAULT = 10.0   // used only when the driver passes a deadline without a margin
// ====================================================

// ---- run_v3 configuration (optional): args[0] = the attempt's step_config.json ------------------
def scriptArgs = (binding.hasVariable('args') && args != null) ? (args as List).collect { it.toString() } : []
def v3cfg = null
if (!scriptArgs.isEmpty() && scriptArgs[0]) {
    def cfgFile = new File(scriptArgs[0])
    if (!cfgFile.isFile()) throw new IllegalArgumentException("[detect] run_v3 config not found: ${cfgFile}")
    // Gson's tree API keeps the nanosecond mtime an exact long (a Map from Gson would hold a lossy double)
    def root = JsonParser.parseString(cfgFile.getText('UTF-8')).getAsJsonObject()
    def num = { o, String k -> (o.has(k) && !o.get(k).isJsonNull()) ? o.get(k).getAsJsonPrimitive() : null }
    def q = root.getAsJsonObject('qpdata_before')
    v3cfg = [attempt_id       : root.get('attempt_id')?.getAsString(),
             qpdata_before    : q.get('exists').getAsBoolean() ?
                     [exists: true, size: q.get('size').getAsLong(), mtime_ns: q.get('mtime_ns').getAsLong()] : [exists: false],
             deadline_epoch_ms: num(root, 'deadline_epoch_ms')?.getAsLong(),
             save_margin_min  : num(root, 'save_margin_min')?.getAsDouble()]
    println "[detect] run_v3 attempt ${v3cfg.attempt_id}: data.qpdata expected ${v3cfg.qpdata_before}"
}

if (getCurrentServer() == null) throw new IllegalStateException("[detect] no image open.")
def entry = getProjectEntry()
if (entry == null) throw new IllegalStateException("[detect] no project entry: open the image from its project.")
def qpPath = entry.getEntryPath().resolve('data.qpdata')
def statOf = { p ->
    Files.exists(p) ? [exists: true, size: Files.size(p), mtime_ns: Files.getLastModifiedTime(p).to(TimeUnit.NANOSECONDS)] :
            [exists: false]
}
def sameStat = { Map a, Map b ->
    a.exists == b.exists && (!a.exists || ((a.size as long) == (b.size as long) && (a.mtime_ns as long) == (b.mtime_ns as long)))
}
// The file this step started from: the driver's record (taken just before QuPath started) or, standalone,
// the file as this script found it.
def expected = v3cfg?.qpdata_before ?: statOf(qpPath)
def requireUnchanged = { String when ->
    def now = statOf(qpPath)
    if (!sameStat(now, expected)) {
        String msg = "[detect] REFUSED ${when}: data.qpdata changed since the step began " +
                "(then size=${expected.size} mtime_ns=${expected.mtime_ns}, now size=${now.size} mtime_ns=${now.mtime_ns}); " +
                "something else wrote it (a GUI save?). Not saving over it."
        println msg
        throw new IllegalStateException(msg)
    }
}
requireUnchanged('at start')   // fail fast, before the GPU work

// Calibration must be in place BEFORE detection: InstanSeg computes its downsample from it, and the
// duplicate-check radius below converts um -> px with it.
setImageType('FLUORESCENCE')
setPixelSizeMicrons(PIXEL_SIZE_UM, PIXEL_SIZE_UM)
def server = getCurrentServer()
def presentNames = server.getMetadata().getChannels().collect { it.getName() }
def missing = INPUT_CHANNELS.findAll { !(it in presentNames) }
if (!missing.isEmpty()) {
    throw new IllegalStateException("[detect] Channel(s) not found: ${missing}. Normalize channel names before detection.")
}
def imageName = entry.getImageName() ?: server.getMetadata()?.getName()
println "[detect] image: ${imageName}"
def cal = server.getPixelCalibration()
double umPerPx2 = cal.getPixelWidthMicrons() * cal.getPixelHeightMicrons()
def hierarchy = getCurrentHierarchy()
def clsOf = { o -> o.getPathClass()?.toString() }
def fmt = { double v -> String.format('%.1f', v) }

// ---- 1. the region annotations, explicitly by classification (never selectAnnotations()) -------
def regionAnns = getAnnotationObjects().findAll { clsOf(it) in REGION_CLASSES }
def notArea = regionAnns.findAll { it.getROI() == null || !it.getROI().isArea() }
if (!notArea.isEmpty())
    throw new IllegalStateException("[detect] ${notArea.size()} ${REGION_CLASSES} annotation(s) are not areas " +
            "(lines/points cannot be segmented): ${notArea.collect { it.getName() ?: it.getID() }}")
def tissues = regionAnns.findAll { clsOf(it) == TISSUE_CLASS }
if (tissues.isEmpty())
    throw new IllegalStateException("[detect] no '${TISSUE_CLASS}' annotation found. Create it before running detection.")
def geomOf = { o -> def g = o.getROI().getGeometry(); g.isValid() ? g : g.buffer(0) }
def tissueUnion = UnaryUnionOp.union(tissues.collect { geomOf(it) })
def label = { o -> "${clsOf(o)}${o.getName() ? " '" + o.getName() + "'" : ''} (${o.getID().toString().take(8)})" }

// ---- 2. classify every non-Tissue region against Tissue: disjoint / contained / partial ---------
def regionRows = []
def selected = new ArrayList(tissues)
def contained = []
regionAnns.findAll { clsOf(it) != TISSUE_CLASS }.each { r ->
    def g = geomOf(r)
    double area = g.getArea()
    double inside = area > 0 ? g.intersection(tissueUnion).getArea() : 0.0
    double frac = area > 0 ? inside / area : 0.0
    String kind = inside * umPerPx2 <= MAX_REGION_OVERLAP_UM2 ? 'disjoint' : (frac >= CONTAINED_MIN_FRACTION ? 'contained' : 'partial')
    regionRows << [id: r.getID().toString(), name: r.getName(), 'class': clsOf(r), kind: kind, area_um2: area * umPerPx2,
                   inside_tissue_um2: inside * umPerPx2, fraction_inside_tissue: frac,
                   outside_tissue_um2: (area - inside) * umPerPx2]
    if (kind == 'disjoint') selected << r
    else if (kind == 'contained') contained << r
}
tissues.each { t -> regionRows << [id: t.getID().toString(), name: t.getName(), 'class': TISSUE_CLASS, kind: 'tissue',
                                   area_um2: geomOf(t).getArea() * umPerPx2] }
regionRows.each { println "[detect] region ${it['class']}${it.name ? " '" + it.name + "'" : ''}: ${it.kind}, " +
        "${fmt(it.area_um2)} um^2" + (it.kind == 'tissue' ? '' : ", ${fmt(it.inside_tissue_um2)} um^2 (${String.format('%.4f', it.fraction_inside_tissue)}) inside ${TISSUE_CLASS}") }
def partial = regionRows.findAll { it.kind == 'partial' }
if (!partial.isEmpty())
    throw new IllegalStateException("[detect] ${partial.size()} region(s) overlap ${TISSUE_CLASS} only partly -- " +
            "segmenting them would detect the shared area twice, skipping them leaves the rest without cells. " +
            "Make each one disjoint from ${TISSUE_CLASS} (<= ${MAX_REGION_OVERLAP_UM2} um^2 shared) or >= " +
            "${CONTAINED_MIN_FRACTION * 100}% inside it: " +
            partial.collect { "${it['class']} '${it.name ?: it.id}' shares ${fmt(it.inside_tissue_um2)} um^2 = " +
                    "${String.format('%.2f', it.fraction_inside_tissue * 100)}% of its area" }.join('; '))
contained.each { println "[detect] ${label(it)} lies inside ${TISSUE_CLASS}: segmented with it, not on its own" }

// ---- 3. selected regions must not overlap each other or be nested -----------------------------
def overlaps = []
for (int i = 0; i < selected.size(); i++) {
    for (int j = i + 1; j < selected.size(); j++) {
        def gi = geomOf(selected[i]), gj = geomOf(selected[j])
        if (!gi.getEnvelopeInternal().intersects(gj.getEnvelopeInternal())) continue
        double shared = gi.intersection(gj).getArea() * umPerPx2
        if (shared > MAX_REGION_OVERLAP_UM2) overlaps << [a: label(selected[i]), b: label(selected[j]), shared_um2: shared]
    }
}
if (!overlaps.isEmpty())
    throw new IllegalStateException("[detect] selected regions overlap by more than ${MAX_REGION_OVERLAP_UM2} um^2 " +
            "(their cells would be segmented twice): " + overlaps.collect { "${it.a} & ${it.b}: ${fmt(it.shared_um2)} um^2" }.join('; '))
def selectedSet = Collections.newSetFromMap(new IdentityHashMap())
selectedSet.addAll(selected)
def hasSelectedAncestor = { obj ->
    def p = obj.getParent()
    while (p != null) { if (selectedSet.contains(p)) return true; p = p.getParent() }
    return false
}
def nested = selected.findAll { hasSelectedAncestor(it) }
if (!nested.isEmpty())
    throw new IllegalStateException("[detect] ${nested.size()} region(s) are nested inside another selected region " +
            "and would be segmented twice: ${nested.collect { label(it) }}. Refusing to run.")
println "[detect] selected ${selected.size()} region(s) — nothing else: " + selected.collect { label(it) }.join(', ')

// ---- 4. clear existing detections so a re-run replaces, never accumulates ----------------------
int before = getDetectionObjects().size()
if (before > 0) {
    println "[detect] clearing ${before} existing detections"
    removeDetections()
}
resetSelection()
hierarchy.getSelectionModel().setSelectedObjects(selected, null)   // for the GUI; InstanSeg gets the list itself
def sel = new ArrayList(hierarchy.getSelectionModel().getSelectedObjects())
if (sel.size() != selected.size() || sel.any { !(clsOf(it) in REGION_CLASSES) })
    throw new IllegalStateException("[detect] selection is not exactly the ${selected.size()} region(s): ${sel.collect { label(it) }}")

// ---- park non-detection children of every selected region at the root ---------------------------
// (after removeDetections, so only annotations etc. remain). Their subtrees move with them.
def root = hierarchy.getRootObject()
def parked = new IdentityHashMap()   // child -> original region parent
selected.each { t -> new ArrayList(t.getChildObjects()).each { c -> parked[c] = t } }
if (!parked.isEmpty()) {
    root.addChildObjects(new ArrayList(parked.keySet()))
    fireHierarchyUpdate()
    println "[detect] parked ${parked.size()} annotation(s) at root during detection: " +
            parked.keySet().countBy { it.getPathClass()?.toString() ?: 'Unclassified' }
}
def restoreParked = {
    parked.groupBy { it.value }.each { t, entries -> t.addChildObjects(new ArrayList(entries.keySet())) }
    fireHierarchyUpdate()
    if (!parked.isEmpty()) println "[detect] restored ${parked.size()} annotation(s) under their regions"
}

// ---- 5. run InstanSeg on exactly the selected regions -------------------------------------------
long t0 = System.currentTimeMillis()
def results
try {
    results = qupath.ext.instanseg.core.InstanSeg.builder()
        .modelPath(MODEL_PATH)
        .device(DEVICE)
        .inputChannels(INPUT_CHANNELS.collect { ColorTransforms.createChannelExtractor(it) })
        .tileDims(TILE_DIMS)
        .interTilePadding(PAD)
        .nThreads(N_THREADS)
        .makeMeasurements(MAKE_MEASUREMENTS)
        .randomColors(false)
        .outputType("Default")
        .build()
        .detectObjects(getCurrentImageData(), selected)
} finally {
    restoreParked()   // also runs if detection throws, so the in-memory hierarchy is never left altered
}
fireHierarchyUpdate()
// detectObjects() catches its own exceptions and per-tile failures; it never throws. Check the
// returned record so a failed or partial run is not saved over the cleared detections.
println "[detect] InstanSeg: ${results}"
if (results.wasInterrupted() || results.nTilesFailed() > 0 || results.nObjectsDetected() == 0) {
    throw new IllegalStateException("[detect] InstanSeg run incomplete (interrupted=${results.wasInterrupted()}, " +
            "failed tiles=${results.nTilesFailed()}/${results.nTilesProcessed()}, objects=${results.nObjectsDetected()}). NOT saving.")
}

def cells = getDetectionObjects()
println String.format("[detect] %,d detections in %.0fs", cells.size(),
        (System.currentTimeMillis() - t0) / 1000.0)

// every selected region got its own detections (children), every contained pLN has cells inside it
def perRegion = selected.collect { r -> [region: label(r), 'class': clsOf(r), detections: r.getChildObjects().count { it.isDetection() }] }
contained.each { r ->
    int n = hierarchy.getAllDetectionsForROI(r.getROI()).size()
    perRegion << [region: label(r), 'class': clsOf(r), detections: n, via: TISSUE_CLASS]
}
perRegion.each { println "[detect]   ${it.region}: ${it.detections} detections" + (it.via ? " (segmented with ${it.via})" : '') }
def emptyRegions = perRegion.findAll { it.detections == 0 }
if (!emptyRegions.isEmpty())
    throw new IllegalStateException("[detect] ${emptyRegions.size()} region(s) received no detections: " +
            "${emptyRegions.collect { it.region }}. NOT saving.")

// ---- 6. verify no duplicates ----------------------------------------------
// Grid-bucket the centroids so this is O(n) rather than O(n^2) on ~2M cells.
double pxSize = cal.hasPixelSizeMicrons() ? cal.getAveragedPixelSizeMicrons() : 1.0
double rPx = DUP_RADIUS_UM / pxSize
// Plain map (not withDefault): withDefault's get() inserts missing keys as a side effect, which
// caused a ConcurrentModificationException when neighbor lookups mutated the map mid-iteration.
// Pair ordering uses a unique per-object index (identityHashCode is not unique and can hide a pair).
def cellList = new ArrayList(cells)
def buckets = [:]
for (int i = 0; i < cellList.size(); i++) {
    def roi = cellList[i].getROI()
    if (roi == null) continue
    def key = [(int) (roi.getCentroidX() / rPx), (int) (roi.getCentroidY() / rPx)]
    buckets.computeIfAbsent(key) { [] } << i
}
int dupPairs = 0
def dupList = []
double pxArea = pxSize * pxSize
for (bucketEntry in new ArrayList(buckets.entrySet())) {
    def (bx, by) = bucketEntry.key
    def near = []
    for (dx in -1..1) for (dy in -1..1) near.addAll(buckets.getOrDefault([bx + dx, by + dy], []))
    for (int ia in bucketEntry.value) {
        def ra = cellList[ia].getROI()
        for (int ib in near) {
            if (ib <= ia) continue
            def rb = cellList[ib].getROI()
            double d = Math.hypot(ra.getCentroidX() - rb.getCentroidX(),
                                  ra.getCentroidY() - rb.getCentroidY())
            if (d > rPx) continue
            double aa = ra.getArea(), ab = rb.getArea()
            if (Math.min(aa, ab) * pxArea < DEBRIS_MAX_UM2) continue   // debris: not a duplicated cell
            if (Math.abs(aa - ab) / Math.max(Math.max(aa, ab), 1e-9) < DUP_AREA_TOL) {
                dupPairs++
                dupList << [a: ia, b: ib, d_um: d * pxSize, area_a_um2: aa * pxArea, area_b_um2: ab * pxArea,
                            x_um: ra.getCentroidX() * pxSize, y_um: ra.getCentroidY() * pxSize]
            }
        }
    }
}
int dupResolveMax = DUP_RESOLVE_MAX_FRACTION > 0 ? Math.max(10, (int) (DUP_RESOLVE_MAX_FRACTION * cellList.size())) : 0
dupList.take(20).each { println String.format("[detect]   duplicate pair at (%.1f, %.1f) um: %.2f um apart, areas %.1f / %.1f um^2",
        it.x_um, it.y_um, it.d_um, it.area_a_um2, it.area_b_um2) }
int dupResolved = 0
if (dupPairs > dupResolveMax) {
    println "ERROR: ${dupPairs} duplicate detection pair(s) found after detection (limit ${dupResolveMax})."
    println "       Two objects share a centroid within ${DUP_RADIUS_UM} um with matching area."
    throw new IllegalStateException("[detect] ${dupPairs} duplicate pairs - detections NOT saved.")
} else if (dupPairs > 0) {
    // the same cell twice (e.g. at a tile seam): keep the first copy
    def drop = dupList.collect { cellList[it.b as int] }.unique()
    removeObjects(drop, true)
    dupResolved = drop.size()
    cells = getDetectionObjects()
    println "[detect] duplicate check: ${dupPairs} pair(s) within ${DUP_RADIUS_UM} um resolved by dropping ${dupResolved} " +
            "second copies (limit ${dupResolveMax}); ${cells.size()} detections remain"
} else {
    println "[detect] duplicate check: PASS (0 pairs within ${DUP_RADIUS_UM} um; debris < ${DEBRIS_MAX_UM2} um^2 not checked)"
}

// ---- 7. save, only over the file this step started from and not too close to the deadline -----
requireUnchanged('to save')
def deadlineMs = v3cfg?.deadline_epoch_ms
double marginMin = (v3cfg?.save_margin_min != null ? v3cfg.save_margin_min : SAVE_MARGIN_MIN_DEFAULT) as double
if (deadlineMs != null && (deadlineMs as long) > 0 &&
        System.currentTimeMillis() + (long) (marginMin * 60000) > (deadlineMs as long)) {
    String msg = String.format("[detect] REFUSED to save: %.1f min left before the step's deadline, margin %.1f min " +
            "(a save cut short leaves data.qpdata half-written). Re-run the step with more time.",
            ((deadlineMs as long) - System.currentTimeMillis()) / 60000.0, marginMin)
    println msg
    throw new IllegalStateException(msg)
}
long s0 = System.currentTimeMillis()
entry.saveImageData(getCurrentImageData())
double saveSeconds = (System.currentTimeMillis() - s0) / 1000.0
V3_RESULT = [ok     : true, changed: true,
             message: "${cells.size()} detections in ${selected.size()} region(s)".toString(),
             details: [regions: regionRows, selected: selected.collect { label(it) }, contained: contained.collect { label(it) },
                       per_region: perRegion, overlaps: overlaps, removed_before: before,
                       instanseg: [objects: results.nObjectsDetected(), tiles: results.nTilesProcessed(),
                                   failed_tiles: results.nTilesFailed(), interrupted: results.wasInterrupted()],
                       detections: cells.size(), duplicate_pairs: dupPairs, duplicates_dropped: dupResolved,
                       duplicate_pairs_detail: dupList.take(50), save_seconds: saveSeconds,
                       max_region_overlap_um2: MAX_REGION_OVERLAP_UM2, contained_min_fraction: CONTAINED_MIN_FRACTION]]
println "[detect] Done."
